     8	import type { OpenClawConfig } from "../config/types.openclaw.js";
     9	import { collectPluginConfigContractMatches } from "../plugins/config-contract-matches.js";
    10	import { resolvePluginConfigContractsById } from "../plugins/config-contracts.js";
    11	import { isRecord, resolveUserPath } from "../utils.js";
    12	import { collectEnabledInsecureOrDangerousFlagsFromContracts } from "./dangerous-config-flags-core.js";
    13	
    14	/** Collect enabled insecure/dangerous config flags from manifest contracts. */
    15	export function collectEnabledInsecureOrDangerousFlags(cfg: OpenClawConfig): string[] {
    16	  const pluginEntries = cfg.plugins?.entries;
    17	  if (!isRecord(pluginEntries)) {
    18	    return collectEnabledInsecureOrDangerousFlagsFromContracts(cfg);
    19	  }
    20	  const pluginIds = Object.keys(pluginEntries);
    21	
    22	  const defaultAgentId = tryResolveDefaultAgentId(cfg);
    23	  const workspaceDirs = new Set<string | undefined>();
    24	  if (defaultAgentId) {
    25	    workspaceDirs.add(resolveAgentWorkspaceDir(cfg, defaultAgentId));
    26	  } else {
    27	    const roster = listAgentEntries(cfg);
    28	    let hasInheritedWorkspace = roster.length === 0;
    29	    for (const entry of roster) {
    30	      const workspace = resolveAgentConfig(cfg, entry.id)?.workspace?.trim();
    31	      if (workspace) {
    32	        workspaceDirs.add(resolveUserPath(workspace, process.env));
    33	      } else {
    34	        hasInheritedWorkspace = true;
    35	      }
    36	    }
    37	    if (hasInheritedWorkspace) {
    38	      const inheritedWorkspace = cfg.agents?.defaults?.workspace?.trim();
    39	      workspaceDirs.add(
    40	        inheritedWorkspace
    41	          ? resolveUserPath(inheritedWorkspace, process.env)
    42	          : resolveDefaultAgentWorkspaceDir(process.env),
    43	      );
    44	    }
    45	  }
    46	
    47	  const flags = new Set<string>();
    48	  for (const workspaceDir of workspaceDirs) {
    49	    const configContracts = resolvePluginConfigContractsById({
    50	      config: cfg,
    51	      ...(workspaceDir ? { workspaceDir } : {}),
    52	      env: process.env,
    53	      pluginIds,
    54	    });
    55	    for (const flag of collectEnabledInsecureOrDangerousFlagsFromContracts(cfg, {
    56	      collectPluginConfigContractMatches,
    57	      configContractsById: configContracts,
    58	    })) {
    59	      flags.add(flag);
    60	    }
    61	  }
    62	  return [...flags];
    63	}
