     1	import { listAgentEntries } from "../agents/agent-scope-config.js";
     2	import { resolveConfiguredToolPolicies } from "../agents/agent-tools.policy.js";
     3	import { resolveSandboxConfigForAgent } from "../agents/sandbox/config.js";
     4	import { isToolAllowedByPolicies } from "../agents/tool-policy-match.js";
     5	import type { OpenClawConfig } from "../config/config.js";
     6	import type { AgentToolsConfig, ExecToolConfig } from "../config/types.tools.js";
     7	
     8	const MUTATING_FS_TOOLS = ["write", "edit", "apply_patch"] as const;
     9	const RUNTIME_TOOLS = ["exec", "process"] as const;
    10	
    11	/** Scope where exec-like tools remain available while mutating filesystem tools are disabled. */
    12	type ExecFilesystemPolicyDriftHit = {
    13	  scopeLabel: string;
    14	  runtimeTools: string[];
    15	  disabledFilesystemTools: string[];
    16	  sandboxMode: "off" | "non-main" | "all";
    17	  sandboxWorkspaceAccess: "none" | "ro" | "rw";
    18	  execHost: NonNullable<ExecToolConfig["host"]>;
    19	};
    20	
    21	/** Find policy scopes where exec can still mutate files despite disabled fs tools. */
    22	export function collectExecFilesystemPolicyDriftHits(
    23	  cfg: OpenClawConfig,
    24	): ExecFilesystemPolicyDriftHit[] {
    25	  const hits: ExecFilesystemPolicyDriftHit[] = [];
    26	  const globalExec = cfg.tools?.exec;
    27	  const contexts: Array<{
    28	    scopeLabel: string;
    29	    agentId?: string;
    30	    tools?: AgentToolsConfig;
    31	  }> = [{ scopeLabel: "tools" }];
    32	
    33	  for (const agent of listAgentEntries(cfg)) {
    34	    if (!agent || typeof agent !== "object" || typeof agent.id !== "string") {
    35	      continue;
    36	    }
    37	    contexts.push({
    38	      scopeLabel: `agents.entries.${agent.id}.tools`,
    39	      agentId: agent.id,
    40	      tools: agent.tools,
    41	    });
    42	  }
    43	
    44	  for (const context of contexts) {
    45	    const sandbox = resolveSandboxConfigForAgent(cfg, context.agentId);
    46	    const execHost = context.tools?.exec?.host ?? globalExec?.host ?? "auto";
    47	    // Sandboxed all-mode with non-rw workspace access constrains local exec
    48	    // mutations enough that disabling write/edit/apply_patch is not misleading.
    49	    if (
    50	      sandbox.mode === "all" &&
    51	      execHost !== "gateway" &&
    52	      execHost !== "node" &&
    53	      sandbox.workspaceAccess !== "rw"
    54	    ) {
    55	      continue;
    56	    }
    57	
    58	    const policies = resolveConfiguredToolPolicies({
    59	      cfg,
    60	      agentTools: context.tools,
    61	      sandboxMode: sandbox.mode,
    62	      agentId: context.agentId,
    63	    });
    64	    const runtimeTools = RUNTIME_TOOLS.filter((tool) => isToolAllowedByPolicies(tool, policies));
    65	    if (!runtimeTools.includes("exec")) {
    66	      continue;
    67	    }
    68	
    69	    // Drift means every explicit mutating filesystem tool is disabled while a
    70	    // runtime path that can still mutate files remains allowed.
    71	    const disabledFilesystemTools = MUTATING_FS_TOOLS.filter(
    72	      (tool) => !isToolAllowedByPolicies(tool, policies),
    73	    );
    74	    if (disabledFilesystemTools.length !== MUTATING_FS_TOOLS.length) {
    75	      continue;
    76	    }
    77	
    78	    hits.push({
    79	      scopeLabel: context.scopeLabel,
    80	      runtimeTools,
    81	      disabledFilesystemTools,
    82	      sandboxMode: sandbox.mode,
    83	      sandboxWorkspaceAccess: sandbox.workspaceAccess,
    84	      execHost,
    85	    });
    86	  }
    87	
    88	  return hits;
    89	}
